-- candidate_votes
-- ---------------------------------------------------------------------------

-- Scrutin n°519 (17e législature) — motion de censure contre le gouvernement
-- Michel Barnier, déposée après l'engagement de sa responsabilité (49.3) sur
-- le PLFSS 2025. Adoptée le 4 décembre 2024 avec 331 voix, elle a renversé
-- le gouvernement. Source : Assemblée nationale (analyse officielle du scrutin).
insert into candidate_votes (id, candidate_id, institution, legislature, official_vote_id, title, description, theme_id, vote_date, candidate_vote, importance_level, featured, source_name, source_url, source_type, status, verified_at) values
  (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_vote:519-marine-le-pen'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), 'assemblee_nationale', '17e législature', '519', 'Motion de censure contre le gouvernement Michel Barnier', 'Motion déposée par les groupes du Nouveau Front populaire après l''engagement de la responsabilité du gouvernement (article 49, alinéa 3) sur le projet de loi de financement de la Sécurité sociale pour 2025. Son adoption entraîne la démission du gouvernement.', null, '2024-12-04', 'for', 'major', true, 'Assemblée nationale', 'https://www.assemblee-nationale.fr/dyn/17/scrutins/519', 'parliament', 'published', '2026-09-10')
  on conflict (id) do nothing;
