insert into candidate_controversies (id, candidate_id, title, summary, event_date, context, candidate_response, candidate_response_source_url, controversy_status, last_updated, next_review_at, source_name, source_url, source_type, status) values
  (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_controversy:dupont-aignan-fraude-scrutin'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), 'Sanctionné par l''Assemblée nationale pour avoir voté à la place d''un collègue absent', 'Lors d''un vote sur un projet de loi relatif à la gestion de la crise sanitaire, fin juillet 2021, Nicolas Dupont-Aignan a voté depuis le boîtier de son collègue José Évrard, absent. Le Bureau de l''Assemblée nationale l''a sanctionné le 13 octobre 2021 pour « fraude au scrutin » : rappel au règlement et retrait d''un quart de son indemnité parlementaire pour un mois.', '2021-10-13', 'Nicolas Dupont-Aignan a récusé le terme de « fraude », évoquant une « erreur » et un « quiproquo administratif » : il affirme avoir reçu une délégation de vote de José Évrard, mais qu''un document nécessaire à la procédure n''aurait pas été transmis à temps.', null, null, 'disputed', '2026-09-10', null, 'LCP — Assemblée nationale', 'https://lcp.fr/actualites/nicolas-dupont-aignan-sanctionne-par-l-assemblee-le-depute-recuse-la-fraude-et-concede', 'media', 'published')
  on conflict (id) do nothing;
